                "f32",
                "rocdl_mfma_f32_32x32x8bf16_1k",
                VectorElemKind::BF16,
                VectorElemKind::F32,
            },
        };

        return llvm::ArrayRef(kConfigs);
    }

    static const MFMAConfig *Find(int64_t m, int64_t n, int64_t k,
